// Install dependencies:
//   npm install react react-dom carbon-components carbon-components-react

import React from 'react';
import ReactDOM from 'react-dom';
import 'carbon-components/css/carbon-components.min.css';
import { Toggle } from 'carbon-components-react';

function App() {
  return (
    <div style={{ padding: '2rem' }}>
      <h1>Toggle VoiceOver Test</h1>

      {/*
        This Toggle will render two <span> elements for the "Off" and "On"
        labels with aria-hidden="true" which prevents VoiceOver from
        reading them.
      */}
      <Toggle
        id="toggle-1"
        labelText="Enable feature"
        labelA="Off"
        labelB="On"
        defaultToggled={false}
        onToggle={(checked, id, evt) => {
          console.log(`Toggled ${id} to ${checked}`);
        }}
      />
    </div>
  );
}

ReactDOM.render(<App />, document.getElementById('root'));

